changeSet.sql:
CREATE OR REPLACE FUNCTION immutable_unaccent(text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT
    AS $$ SELECT public.unaccent('public.unaccent', $1) $$;

ALTER TABLE knowledge_chunk
    ADD COLUMN content_tsv tsvector
    GENERATED ALWAYS AS (to_tsvector('simple', immutable_unaccent(heading_path || ' ' || content))) STORED;

CREATE INDEX idx_knowledge_chunk_tsv ON knowledge_chunk USING gin (content_tsv);

changeSet.rollback:
DROP INDEX idx_knowledge_chunk_tsv;
ALTER TABLE knowledge_chunk DROP COLUMN content_tsv;
DROP FUNCTION immutable_unaccent(text);
